<script lang="ts">
  import { createEventDispatcher } from 'svelte';
  import { SvelteFlow, Background, Controls, MiniMap, addEdge, MarkerType, Panel } from '@xyflow/svelte';
  import '@xyflow/svelte/dist/style.css';
  import FlowNode from './FlowNode.svelte';
  import { validateWorkflow, nodeCatalog, createWorkflowTemplate } from '../lib/workflow.mjs';
  import { Plus, Save, Copy, Trash2, WandSparkles, Maximize2, RotateCcw, AlertTriangle, CheckCircle2, Search } from 'lucide-svelte';
  export let nodes:any[]=[]; export let edges:any[]=[]; export let saveState='Saved';
  const dispatch=createEventDispatcher();
  const nodeTypes={workflow:FlowNode};
  const groups=['Triggers','Conversation','Logic','Actions','Endings'];
  let selectedId=''; let selectedEdgeId=''; let flow:any; let showPicker=false; let category='Triggers'; let issues:any[]=[]; let template=''; let undoStack:any[]=[]; let redoStack:any[]=[];
  $: selected=nodes.find(n=>n.id===selectedId);
  $: issues=validateWorkflow({nodes,edges});
  function snapshot(){undoStack=[...undoStack.slice(-29),JSON.stringify({nodes,edges})];redoStack=[];}
  function changed(){dispatch('workflowchange',{nodes,edges});}
  function addNode(type:string){snapshot();const id=`${type}-${crypto.randomUUID().slice(0,8)}`;const meta:any=nodeCatalog[type];const config:any={name:meta.label};if(type==='ask')Object.assign(config,{question:'',answerType:'free text',required:true,maxRetries:2,noAnswer:''});if(type==='collect')config.fields=[{name:'',type:'text',required:true}];if(['condition','condition_check'].includes(type))Object.assign(config,{variable:'',operator:'equals',value:''});if(type==='required_field')config.field='';if(['action','handoff'].includes(type))Object.assign(config,{instructions:'',fallback:''});if(['inform','confirm','end','success','fallback'].includes(type))config.instructions='';let slot=0;let position={x:80,y:80};do{position={x:80+(slot%4)*300,y:80+Math.floor(slot/4)*190};slot++;}while(nodes.some(n=>Math.abs(n.position.x-position.x)<220&&Math.abs(n.position.y-position.y)<120));const node={id,type:'workflow',position,data:{kind:type,label:meta.label,config}};nodes=[...nodes,node];selectedId=id;selectedEdgeId='';showPicker=false;changed();}
  function updateConfig(key:string,value:any){if(!selected)return;snapshot();nodes=nodes.map(n=>n.id===selectedId?{...n,data:{...n.data,config:{...n.data.config,[key]:value}}}:n);changed();}
  function deleteSelected(){if(!selected)return;snapshot();nodes=nodes.filter(n=>n.id!==selectedId);edges=edges.filter(e=>e.source!==selectedId&&e.target!==selectedId);selectedId='';changed();}
  function duplicate(){if(!selected)return;snapshot();const copy={...selected,id:`${selected.data.kind}-${crypto.randomUUID().slice(0,8)}`,position:{x:selected.position.x+70,y:selected.position.y+70},data:structuredClone(selected.data)};nodes=[...nodes,copy];selectedId=copy.id;changed();}
  function connect(event:any){snapshot();edges=addEdge({...event.detail,id:`edge-${crypto.randomUUID().slice(0,8)}`,animated:false,markerEnd:MarkerType.ArrowClosed,label:event.detail.sourceHandle?.toUpperCase()},edges);selectedEdgeId='';changed();}
  function applyTemplate(){if(!template)return;if(nodes.length&&!confirm('Replace the current workflow with this template?'))return;snapshot();const w=createWorkflowTemplate(template);nodes=w.nodes.map(n=>({...n,type:'workflow'}));edges=w.edges;selectedId='';template='';changed();flow?.fitView?.({padding:.25});}
  function applyAutoLayout(){snapshot();const levels=new Map<string,number>();const roots=nodes.filter(n=>n.data.kind.startsWith('trigger_'));const walk=(id:string,l:number,seen:Set<string>)=>{if(seen.has(id))return;seen.add(id);levels.set(id,Math.min(levels.get(id)??99,l));for(const e of edges.filter(e=>e.source===id))walk(e.target,l+1,seen)};roots.forEach(n=>walk(n.id,0,new Set()));const rows=new Map<number,number>();nodes=nodes.map(n=>{const level=levels.get(n.id)??0,row=rows.get(level)||0;rows.set(level,row+1);return {...n,position:{x:80+level*310,y:80+row*180}}});changed();flow?.fitView?.({padding:.2});}
  function clearWorkflow(){if(!nodes.length)return;if(!confirm('Clear every node and connection in this workflow? This change will be saved.'))return;snapshot();nodes=[];edges=[];selectedId='';selectedEdgeId='';changed();}
  function restore(stack:any[],other:any[]){if(!stack.length)return;const target=JSON.stringify({nodes,edges});const parsed=JSON.parse(stack.at(-1));other=[...other,target];nodes=parsed.nodes;edges=parsed.edges;changed();return {stack:stack.slice(0,-1),other};}
  function undo(){const s=restore(undoStack,redoStack);if(s){undoStack=s.stack;redoStack=s.other}}
  function redo(){const s=restore(redoStack,undoStack);if(s){redoStack=s.stack;undoStack=s.other}}
  function focusIssue(issue:any){if(issue.nodeId){selectedId=issue.nodeId;flow?.fitView?.({nodes:[{id:issue.nodeId}],padding:.7,duration:350});}}
  function edgeLabel(id:string,label:string){snapshot();edges=edges.map(e=>e.id===id?{...e,label}:e);changed();}
  function addField(){const fields=[...(selected?.data.config.fields||[]),{name:'',type:'text',required:false}];updateConfig('fields',fields)}
  function setField(index:number,key:string,value:any){const fields=[...(selected?.data.config.fields||[])];fields[index]={...fields[index],[key]:value};updateConfig('fields',fields)}
  function onKey(event:KeyboardEvent){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo()}else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();redo()}else if(['Delete','Backspace'].includes(event.key)&&!['INPUT','TEXTAREA','SELECT'].includes((event.target as HTMLElement)?.tagName)){if(selected)deleteSelected()}}
</script>
<svelte:window on:keydown={onKey}/>
<div class="workflow-editor">
  <header class="editor-head"><div><span class="eyebrow">VISUAL CONVERSATION DESIGNER</span><h2>Workflow</h2></div><div class="head-tools"><span class="save-state" data-state={saveState}>{#if saveState==='Saved'}<CheckCircle2 size={14}/>{:else if saveState==='Save failed'}<AlertTriangle size={14}/>{:else}<Save size={14}/>{/if}{saveState}</span><select bind:value={template} on:change={applyTemplate}><option value="">Templates…</option><option>Appointment Booking</option><option>Customer Support</option><option>Lead Qualification</option></select><button on:click={()=>showPicker=!showPicker}><Plus size={14}/> Add node</button><button on:click={applyAutoLayout}><WandSparkles size={14}/> Auto layout</button><button on:click={()=>flow?.fitView?.({padding:.2})} title="Fit to view"><Maximize2 size={14}/></button><button on:click={()=>flow?.setViewport?.({x:0,y:0,zoom:1})} title="Reset view"><RotateCcw size={14}/></button><button on:click={undo} disabled={!undoStack.length} title="Undo">↶</button><button on:click={redo} disabled={!redoStack.length} title="Redo">↷</button><button on:click={clearWorkflow} title="Clear workflow">Clear</button></div></header>
  {#if showPicker}<div class="picker"><nav>{#each groups as g}<button class:active={category===g} on:click={()=>category=g}>{g}</button>{/each}</nav><div class="picker-list">{#each Object.entries(nodeCatalog).filter(([_,v]:any)=>v.category===category) as [type,meta]:any}<button on:click={()=>addNode(type)}><strong>{meta.label}</strong><small>{meta.description}</small><Plus size={14}/></button>{/each}</div></div>{/if}
  <div class="editor-main"><section class="canvas-wrap" aria-label="Workflow canvas">
    {#if !nodes.length}<div class="empty"><div class="empty-symbol"><Search size={22}/></div><strong>Start with a conversation trigger</strong><p>Add a node or choose a template. Connect steps by dragging from a handle.</p><button on:click={()=>showPicker=true}><Plus size={14}/> Add first node</button></div>{/if}
    <SvelteFlow bind:this={flow} bind:nodes bind:edges {nodeTypes} fitView deleteKeyCode={['Backspace','Delete']} selectionOnDrag panOnDrag={true} on:connect={connect} on:nodeclick={(e)=>{selectedId=e.detail.node.id;selectedEdgeId='';}} on:edgeclick={(e)=>{selectedId='';selectedEdgeId=e.detail.edge.id;}} on:nodeschange={()=>changed()} on:edgeschange={()=>changed()} on:reconnect={(e)=>{snapshot();edges=edges.map(edge=>edge.id===e.detail.edge.id?{...edge,...e.detail.connection}:edge);changed()}}>
      <Background color="#252d41" gap={24} variant="dots"/><Controls/><MiniMap pannable zoomable nodeColor={(n:any)=>n.data.kind.startsWith('trigger_')?'#a687ff':['condition','condition_check','required_field'].includes(n.data.kind)?'#55cbe0':['end','success','fallback'].includes(n.data.kind)?'#a3d66b':'#39445e'} maskColor="#070910aa"/><Panel position="bottom-left"><div class="canvas-legend"><span><i class="violet"></i>Trigger</span><span><i class="cyan"></i>Conversation / Logic</span><span><i class="lime"></i>Ending</span><span>{nodes.length} nodes · {edges.length} connections</span></div></Panel>
    </SvelteFlow>
  </section>
  <aside class="inspector"><div class="inspector-title"><div><span class="eyebrow">{selectedEdgeId?'CONNECTION INSPECTOR':'NODE INSPECTOR'}</span><h3>{selectedEdgeId?'Edit connection':selected?.data?.config?.name||selected?.data?.label||'Select a node'}</h3></div>{#if selected}<div class="icon-actions"><button title="Duplicate" on:click={duplicate}><Copy size={14}/></button><button title="Delete" on:click={deleteSelected}><Trash2 size={14}/></button></div>{/if}</div>
    {#if selectedEdgeId}<div class="form-scroll"><label>Connection label<input value={edges.find(e=>e.id===selectedEdgeId)?.label||''} on:input={(e)=>edgeLabel(selectedEdgeId,e.currentTarget.value)}/></label><button class="subtle" on:click={()=>{snapshot();edges=edges.filter(e=>e.id!==selectedEdgeId);selectedEdgeId='';changed()}}><Trash2 size={13}/> Delete connection</button><p class="hint">Drag the connection endpoint to another handle to reconnect it.</p></div>{/if}
    {#if selected}<div class="form-scroll"><label>Node name<input value={selected.data.config?.name||''} on:input={(e)=>updateConfig('name',e.currentTarget.value)}/></label>
      {#if selected.data.kind==='ask'}<label>Question to ask<textarea rows="3" value={selected.data.config.question||''} on:input={(e)=>updateConfig('question',e.currentTarget.value)}></textarea></label><label>Expected answer<select value={selected.data.config.answerType||'free text'} on:change={(e)=>updateConfig('answerType',e.currentTarget.value)}><option>free text</option><option>yes/no</option><option>number</option><option>date</option><option>time</option></select></label><label class="check"><input type="checkbox" checked={!!selected.data.config.required} on:change={(e)=>updateConfig('required',e.currentTarget.checked)}/> Required answer</label><label>Maximum retries<input type="number" min="0" max="10" value={selected.data.config.maxRetries??2} on:input={(e)=>updateConfig('maxRetries',Number(e.currentTarget.value))}/></label><label>If caller does not answer<textarea rows="2" value={selected.data.config.noAnswer||''} on:input={(e)=>updateConfig('noAnswer',e.currentTarget.value)}></textarea></label>
      {:else if selected.data.kind==='collect'}<strong>Fields to collect</strong>{#each selected.data.config.fields||[] as field,i}<div class="field-row"><input placeholder="Field name" value={field.name} on:input={(e)=>setField(i,'name',e.currentTarget.value)}/><select value={field.type||'text'} on:change={(e)=>setField(i,'type',e.currentTarget.value)}><option>text</option><option>number</option><option>date</option><option>time</option><option>email</option></select><input placeholder="Validation" value={field.validation||''} on:input={(e)=>setField(i,'validation',e.currentTarget.value)}/><label class="check"><input type="checkbox" checked={!!field.required} on:change={(e)=>setField(i,'required',e.currentTarget.checked)}/> Required</label></div>{/each}<button class="subtle" on:click={addField}><Plus size={13}/> Add field</button><label class="check"><input type="checkbox" checked={!!selected.data.config.confirm} on:change={(e)=>updateConfig('confirm',e.currentTarget.checked)}/> Read fields back for confirmation</label>
      {:else if ['condition','condition_check','required_field'].includes(selected.data.kind)}{#if selected.data.kind==='required_field'}<label>Field name<input value={selected.data.config.field||''} on:input={(e)=>updateConfig('field',e.currentTarget.value)}/></label>{:else}<label>Variable<input value={selected.data.config.variable||selected.data.config.condition||''} on:input={(e)=>updateConfig('variable',e.currentTarget.value)}/></label><label>Operator<select value={selected.data.config.operator||'equals'} on:change={(e)=>updateConfig('operator',e.currentTarget.value)}><option>equals</option><option>does not equal</option><option>contains</option><option>is present</option><option>is absent</option><option>is greater than</option></select></label><label>Comparison value<input value={selected.data.config.value||''} on:input={(e)=>updateConfig('value',e.currentTarget.value)}/></label>{/if}<p class="hint">Connect TRUE and FALSE handles to distinct paths.</p>
      {:else if selected.data.kind==='action'}<div class="warning"><AlertTriangle size={14}/> Action steps are instructions only unless a real integration is configured.</div><label>Action requirement<textarea rows="4" value={selected.data.config.instructions||''} on:input={(e)=>updateConfig('instructions',e.currentTarget.value)}></textarea></label><p class="hint">Connect SUCCESS and FAILURE branches. Deployment validation blocks unconfigured external integrations.</p>
      {:else if selected.data.kind==='integration'}<label>Integration<select value={selected.data.config.integration||''} on:change={(e)=>updateConfig('integration',e.currentTarget.value)}><option value="">Choose integration</option><option>Calendar</option><option>CRM</option><option>Custom API</option></select></label><label>Action<input value={selected.data.config.action||''} on:input={(e)=>updateConfig('action',e.currentTarget.value)}/></label><div class="warning"><AlertTriangle size={14}/> No integrations are currently executable in VoxFlow. This node blocks deployment until an executor exists.</div>
      {:else if selected.data.kind==='handoff'}<label>Handoff instructions<textarea rows="4" value={selected.data.config.instructions||''} on:input={(e)=>updateConfig('instructions',e.currentTarget.value)}></textarea></label><label>Escalation reason<input value={selected.data.config.reason||''} on:input={(e)=>updateConfig('reason',e.currentTarget.value)}/></label><label>When no human is available<textarea rows="3" value={selected.data.config.fallback||''} on:input={(e)=>updateConfig('fallback',e.currentTarget.value)}></textarea></label>
      {:else}<label>{['inform'].includes(selected.data.kind)?'Information / instructions':['confirm'].includes(selected.data.kind)?'Details to confirm':'Completion message / end reason'}<textarea rows="4" value={selected.data.config.instructions||selected.data.config.message||selected.data.config.reason||''} on:input={(e)=>updateConfig(selected.data.kind==='end'||selected.data.kind==='success'||selected.data.kind==='fallback'?'message':'instructions',e.currentTarget.value)}></textarea></label>{#if selected.data.kind.startsWith('trigger_')}<p class="hint">The configured first message is preserved as the agent greeting.</p>{/if}{/if}
    </div>{:else}<p class="hint">Choose a node on the canvas to edit its behavior, branches, and recovery path.</p>{/if}
    <div class="validation"><div class="validation-head"><strong>Validation</strong><span>{issues.filter(i=>i.severity==='error').length} errors · {issues.filter(i=>i.severity==='warning').length} warnings</span></div>{#if issues.length}{#each issues as issue}<button class="issue" class:error={issue.severity==='error'} on:click={()=>focusIssue(issue)}><span>{issue.severity==='error'?'●':'▲'}</span>{issue.message}</button>{/each}{:else}<div class="valid"><CheckCircle2 size={14}/> Workflow is ready to deploy.</div>{/if}</div>
  </aside></div>
</div>
<style>
.workflow-editor{--bg:#080a11;--surface:#101421;--line:#292f40;--text:#edf0fb;--muted:#9299ad;color:var(--text);height:min(76vh,850px);min-height:590px;background:var(--bg);border:1px solid var(--line);border-radius:13px;overflow:hidden;position:relative;font:12px Manrope,system-ui}.editor-head{height:68px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;background:#0d111c;border-bottom:1px solid var(--line)}.editor-head h2{font-size:18px;margin:3px 0}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:1.2px;color:#9f91e5}.head-tools{display:flex;align-items:center;gap:6px}.head-tools button,.head-tools select,.picker button{height:31px;border:1px solid #343b50;background:#161b2a;color:#e9eaf4;border-radius:6px;padding:0 9px;display:inline-flex;align-items:center;gap:6px;cursor:pointer;font:10px inherit}.head-tools button:hover,.head-tools select:hover{border-color:#a687ff}.head-tools button:disabled{opacity:.4}.save-state{display:flex;align-items:center;gap:5px;font-size:10px;color:#a3d66b;margin-right:8px}.save-state[data-state='Saving...'],.save-state[data-state='Unsaved changes']{color:#e4c878}.save-state[data-state='Save failed']{color:#ff8585}.editor-main{height:calc(100% - 68px);display:grid;grid-template-columns:minmax(0,1fr) 300px}.canvas-wrap{position:relative;min-width:0;background:#080b13}.canvas-wrap :global(.svelte-flow){background:radial-gradient(#283149 1px,transparent 1px);background-size:24px 24px}.canvas-wrap :global(.svelte-flow__controls){background:#111725;border:1px solid #30384c;box-shadow:none}.canvas-wrap :global(.svelte-flow__controls-button){background:#141a29;fill:#e2e5f0;border-bottom:1px solid #30384c}.canvas-wrap :global(.svelte-flow__controls-button:hover){background:#252d42}.canvas-wrap :global(.svelte-flow__minimap){background:#111725;border:1px solid #30384c;border-radius:7px}.canvas-wrap :global(.svelte-flow__edge-path){stroke:#7f75b8;stroke-width:2}.canvas-wrap :global(.svelte-flow__edge-text){fill:#dce1f3;font-size:10px}.canvas-wrap :global(.svelte-flow__edge-textbg){fill:#151a28}.canvas-wrap :global(.svelte-flow__panel){margin:12px}.canvas-legend{display:flex;gap:12px;align-items:center;color:#a9afc2;font-size:9px;padding:8px 10px;background:#111725eF;border:1px solid #2b3245;border-radius:7px}.canvas-legend span{display:flex;gap:5px;align-items:center}.canvas-legend i{width:7px;height:7px;border-radius:50%;background:#a687ff}.canvas-legend i.cyan{background:#55cbe0}.canvas-legend i.lime{background:#a3d66b}.empty{position:absolute;z-index:4;left:50%;top:50%;transform:translate(-50%,-50%);text-align:center;max-width:350px;padding:20px;border:1px solid #30384c;background:#101421ed;border-radius:12px}.empty-symbol{margin:auto;background:#252039;color:#baa5ff;width:38px;height:38px;display:grid;place-items:center;border-radius:10px}.empty strong{display:block;margin-top:12px;font-size:14px}.empty p,.hint{color:var(--muted);font-size:10px;line-height:1.6}.empty button{background:#a687ff;color:#100d1a;border:0;border-radius:6px;padding:8px 12px;display:inline-flex;gap:5px;align-items:center;cursor:pointer;font-size:10px}.inspector{background:#101421;border-left:1px solid var(--line);display:flex;flex-direction:column;min-height:0}.inspector-title{padding:14px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.inspector-title h3{font-size:14px;margin:4px 0 0}.icon-actions{display:flex;gap:5px}.icon-actions button{background:#1b2030;border:1px solid #343b50;color:#ccd1e0;width:28px;height:28px;border-radius:5px;cursor:pointer;display:grid;place-items:center}.form-scroll{padding:13px;overflow:auto;display:grid;align-content:start;gap:11px}.form-scroll label{font-size:10px;color:#bfc5d6;display:grid;gap:5px}.form-scroll input,.form-scroll select,.form-scroll textarea{background:#090d16;border:1px solid #31384a;border-radius:5px;padding:8px;color:#eef0f8;font:11px inherit;outline:none}.form-scroll input:focus,.form-scroll textarea:focus,.form-scroll select:focus{border-color:#a687ff}.form-scroll label.check{display:flex;align-items:center;gap:7px}.form-scroll input[type=checkbox]{accent-color:#a687ff}.field-row{display:grid;gap:6px;padding:8px;background:#151a28;border:1px solid #2b3242;border-radius:6px}.field-row label.check{display:flex;align-items:center}.subtle{display:flex;align-items:center;gap:5px;background:none;border:1px dashed #4a5269;color:#bbc1d3;padding:7px;border-radius:5px;cursor:pointer}.hint{margin:0}.warning{display:flex;gap:7px;align-items:flex-start;background:#382a1c;color:#ffd08a;border:1px solid #70532e;padding:9px;border-radius:6px;font-size:10px;line-height:1.5}.validation{margin-top:auto;padding:12px;border-top:1px solid var(--line);max-height:38%;overflow:auto}.validation-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.validation-head strong{font-size:11px}.validation-head span{font-size:9px;color:var(--muted)}.issue{width:100%;text-align:left;display:flex;gap:7px;align-items:flex-start;background:#26171b;border:1px solid #542a33;color:#f3b6bd;border-radius:5px;padding:7px;margin-top:5px;font-size:9px;cursor:pointer}.issue:not(.error){background:#2b271b;border-color:#66542e;color:#e6d39a}.valid{display:flex;align-items:center;gap:6px;color:#a3d66b;font-size:10px}.picker{position:absolute;z-index:10;top:57px;left:12px;width:340px;background:#111725;border:1px solid #333b50;border-radius:9px;box-shadow:0 18px 40px #000b;padding:9px}.picker nav{display:flex;gap:4px;overflow-x:auto}.picker nav button{font-size:9px}.picker nav button.active{border-color:#a687ff;color:#c7b7ff}.picker-list{margin-top:7px}.picker-list>button{width:100%;height:auto;min-height:52px;text-align:left;display:grid;grid-template-columns:1fr auto;padding:8px;margin-top:4px}.picker-list strong{font-size:10px}.picker-list small{grid-column:1;color:#a0a7bb;font-size:9px;line-height:1.4}.picker-list svg{grid-column:2;grid-row:1/3;color:#a687ff}.workflow-editor :global(.svelte-flow__attribution){display:none}@media(max-width:900px){.editor-main{grid-template-columns:minmax(0,1fr) 265px}.head-tools{gap:3px}.head-tools button{padding:0 6px}.save-state{font-size:9px}}@media(max-width:680px){.workflow-editor{height:80vh}.editor-head{height:auto;min-height:68px;align-items:flex-start;gap:7px;flex-direction:column;padding:10px}.head-tools{max-width:100%;overflow:auto}.editor-main{height:calc(100% - 95px);grid-template-columns:1fr}.inspector{position:absolute;right:8px;top:8px;bottom:8px;width:min(290px,88%);z-index:6;box-shadow:0 10px 35px #000b;border:1px solid var(--line);border-radius:9px}.canvas-legend{flex-wrap:wrap}.picker{top:90px}}
</style>
